  "tool": {
    "id": "sequence-editor-toolkit",
    "name": "Sequence Editor Toolkit",
    "description": "Edit, trim, translate, and manipulate DNA/RNA/protein sequences. Supports trimming, extracting regions, reverse complement, translation, transcription, quality filtering (FASTQ), masking, find/replace, and more. Intelligently chooses instant execution for small files (<5MB) or background processing for large files.",
    "category": "algorithm",
    "parameters": [
      {
        "name": "inputFile",
        "type": "string",
        "required": true,
        "description": "Input sequence file (FASTA, FASTQ, or GenBank format)"
      },
      {
        "name": "operation",
        "type": "select",
        "required": true,
        "description": "Editing operation to perform on sequences",
        "options": [
          "trim",
          "extract",
          "reverse_complement",
          "translate",
          "transcribe",
          "case_convert",
          "quality_trim",
          "quality_filter",
          "length_filter",
          "remove_ambiguous",
          "mask_region",
          "find_replace",
          "concatenate",
          "extract_by_id",
          "deduplicate",
          "subsample"
        ]
      },
      {
        "name": "outputFile",
        "type": "string",
        "required": false,
        "description": "Output filename (default: input_edited.ext)"
      },
      {
        "name": "startPosition",
        "type": "number",
        "required": false,
        "min": 1,
        "description": "Start position for trim/extract (1-indexed, inclusive)",
        "showWhen": {
          "parameter": "operation",
          "value": [
            "trim",
            "extract"
          ]
        }
      },
      {
        "name": "endPosition",
        "type": "number",
        "required": false,
        "min": 1,
        "description": "End position for trim/extract (1-indexed, inclusive)",
        "showWhen": {
          "parameter": "operation",
          "value": [
            "trim",
            "extract"
          ]
        }
      },
      {
        "name": "trimStart",
        "type": "number",
        "required": false,
        "min": 0,
        "defaultValue": 0,
        "description": "Number of bases to trim from 5' end (start)",
        "showWhen": {
          "parameter": "operation",
          "value": "trim"
        }
      },
      {
        "name": "trimEnd",
        "type": "number",
        "required": false,
        "min": 0,
        "defaultValue": 0,
        "description": "Number of bases to trim from 3' end (end)",
        "showWhen": {
          "parameter": "operation",
          "value": "trim"
        }
      },
      {
        "name": "readingFrame",
        "type": "select",
        "required": false,
        "options": [
          "1",
          "2",
          "3",
          "-1",
          "-2",
          "-3"
        ],
        "defaultValue": "1",
        "description": "Reading frame for translation (1-3: forward, -1 to -3: reverse complement)",
        "showWhen": {
          "parameter": "operation",
          "value": "translate"
        }
      },
      {
        "name": "geneticCode",
        "type": "number",
        "required": false,
        "min": 1,
        "defaultValue": 1,
        "description": "NCBI genetic code table number (default: 1 = Standard)",
        "showWhen": {
          "parameter": "operation",
          "value": "translate"
        }
      },
      {
        "name": "qualityThreshold",
        "type": "number",
        "required": false,
        "min": 0,
        "max": 40,
        "defaultValue": 20,
        "description": "Phred quality score threshold",
        "showWhen": {
          "parameter": "operation",
          "value": [
            "quality_trim",
            "quality_filter"
          ]
        }
      },
      {
        "name": "minQualityScore",
        "type": "number",
        "required": false,
        "min": 0,
        "max": 40,
        "defaultValue": 20,
        "description": "Minimum average quality score to keep sequence",
        "showWhen": {
          "parameter": "operation",
          "value": "quality_filter"
        }
      },
      {
        "name": "windowSize",
        "type": "number",
        "required": false,
        "min": 1,
        "defaultValue": 4,
        "description": "Sliding window size for quality trimming",
        "showWhen": {
          "parameter": "operation",
          "value": "quality_trim"
        }
      },
      {
        "name": "minLength",
        "type": "number",
        "required": false,
        "min": 1,
        "description": "Minimum sequence length to keep",
        "showWhen": {
          "parameter": "operation",
          "value": "length_filter"
        }
      },
      {
        "name": "maxLength",
        "type": "number",
        "required": false,
        "min": 1,
        "description": "Maximum sequence length to keep",
        "showWhen": {
          "parameter": "operation",
          "value": "length_filter"
        }
      },
      {
        "name": "caseType",
        "type": "select",
        "required": false,
        "options": [
          "upper",
          "lower",
          "toggle"
        ],
        "defaultValue": "upper",
        "description": "Case conversion type",
        "showWhen": {
          "parameter": "operation",
          "value": "case_convert"
        }
      },
      {
        "name": "maskStart",
        "type": "number",
        "required": false,
        "min": 1,
        "description": "Start position of region to mask (1-indexed)",
        "showWhen": {
          "parameter": "operation",
          "value": "mask_region"
        }
      },
      {
        "name": "maskEnd",
        "type": "number",
        "required": false,
        "min": 1,
        "description": "End position of region to mask (1-indexed)",
        "showWhen": {
          "parameter": "operation",
          "value": "mask_region"
        }
      },
      {
        "name": "maskChar",
        "type": "string",
        "required": false,
        "defaultValue": "N",
        "description": "Character to use for masking (default: N)",
        "showWhen": {
          "parameter": "operation",
          "value": "mask_region"
        }
      },
      {
        "name": "searchPattern",
        "type": "string",
        "required": false,
        "description": "Pattern to search for in sequences",
        "showWhen": {
          "parameter": "operation",
          "value": "find_replace"
        }
      },
      {
        "name": "replaceWith",
        "type": "string",
        "required": false,
        "description": "Replacement string",
        "showWhen": {
          "parameter": "operation",
          "value": "find_replace"
        }
      },
      {
        "name": "useRegex",
        "type": "boolean",
        "required": false,
        "defaultValue": false,
        "description": "Use regular expression for search pattern",
        "showWhen": {
          "parameter": "operation",
          "value": "find_replace"
        }
      },
      {
        "name": "sequenceIds",
        "type": "string",
        "required": false,
        "description": "Comma-separated list of sequence IDs to extract",
        "showWhen": {
          "parameter": "operation",
          "value": "extract_by_id"
        }
      },
      {
        "name": "sampleSize",
        "type": "number",
        "required": false,
        "min": 1,
        "description": "Number of sequences to randomly sample",
        "showWhen": {
          "parameter": "operation",
          "value": "subsample"
        }
      },
      {
        "name": "randomSeed",
        "type": "number",
        "required": false,
        "description": "Random seed for reproducible sampling",
        "showWhen": {
          "parameter": "operation",
          "value": "subsample"
        }
      }
    ],
    "executionMode": "instant",
    "version": "1.0.0",
    "author": "smarts.bio",
    "tags": [
      "sequence-editing",
      "sequence-manipulation",
      "bioinformatics",
      "dna",
      "rna",
      "protein",
      "translation",
      "quality-control"
    ]
  },
  "timestamp": "2026-11-04T13:19:44.598Z"
}

